fests.exports.get", "supabase.tenant.manifests.exports.purge"]'::jsonb) OR NOT(r.input_schema#>'{properties,operations,items,enum}' ?& ARRAY['supabase.tenant.content.export','supabase.tenant.content.exports.get','supabase.tenant.content.exports.purge']) THEN RAISE EXCEPTION 'content_consent_names_invalid';END IF;
 IF r.input_schema#>'{properties,operations,items,enum}' ?| ARRAY['supabase.tenant.content.exports.download','supabase.tenant.content.exports.available'] THEN RAISE EXCEPTION 'content_user_routes_adopted_owner_consent';END IF;
 IF r.api_exposed OR r.ai_exposed OR r.verified OR NOT has_function_privilege('authenticated','public.sandy_supabase_tenant_consent_set(text[],text[],boolean,timestamptz)','EXECUTE') OR has_function_privilege('service_role','public.sandy_supabase_tenant_consent_set(text[],text[],boolean,timestamptz)','EXECUTE') THEN RAISE EXCEPTION 'content_consent_closed_user_boundary_changed';END IF;
