SELECT jsonb_build_object('passed',true,'layer','administrative_database_component','real_auth_session_tested',false,'provider_calls',0,'checks',jsonb_build_array('exact60_consent_hash','prior57_plus_three_owner_artifact_controls','user_routes_not_owner_consent','closed_flags_and_actual_user_consent_ACL_preserved')) AS evidence;
